bool Radar::radarToWorld(const ICoord2D *radar, Coord3D *world)
{
    if (!radar || !world)
        return false;
    ICoord2D cell = *radar;
    if (cell.x < 0)
        cell.x = 0;
    if (cell.x >= 128)
        cell.x = 127;
    if (cell.y < 0)
        cell.y = 0;
    if (cell.y >= 128)
        cell.y = 127;
    world->x = cell.x * m_xSample;
    world->y = m_ySample * cell.y;
    world->z = TheTerrainLogic->getGroundHeight(world->x, world->y, 0);
    return true;
}

