// FUNCTION: BFME2 0x002D7DD5 size=147 name=?update@Radar@@UAEXXZ evidence=N:ledger tier=A
void Radar::update()
{
    UnsignedInt now = TheGameClient->getFrame();
    m_radarForceOn = true;
    for (int i = 0; i < 64; i++) {
        RadarEvent &event = m_events[i];
        if (event.m_active == true && event.m_createFrame != 0 && now > event.m_dieFrame) {
            event.m_active = false;
            if (event.m_ref.m_target)
                event.m_ref.clearRef();
        }
    }
    if (m_queuedRefreshFrame != 0) {
        UnsignedInt elapsed = TheGameLogic->getFrame() - m_queuedRefreshFrame;
        if ((Real)elapsed > (Real)BfmeLogicFramesPerSecond * 3.0f)
            refreshTerrain(TheTerrainLogic);
    }
}

// FUNCTION: BFME2 0x002D7E68 size=326 name=?rva002D7E68@Radar@@QAEXPAX@Z evidence=?:placeholder tier=A
void Radar::rva002D7E68(void *terrainArg)
{
    TerrainLogic *terrain = (TerrainLogic *)terrainArg;
    newMap();
    reset();
    Region3D *extent = &m_mapExtent;
    terrain->largestBoundaryExtent(extent);
    m_xSample = extent->width() * 0.0078125f;
    m_ySample = extent->height() * 0.0078125f;
    int terrainSamples = 0;
    int waterSamples = 0;
    m_terrainAverageZ = 0.0f;
    m_waterAverageZ = 0.0f;
    for (int y = 0; y < 128; y++) {
        for (int x = 0; x < 128; x++) {
            ICoord2D radar;
            radar.x = x;
            radar.y = y;
            Coord3D world;
            radarToWorld(&radar, &world);
            int z = (int)terrain->getGroundHeight(world.x, world.y, 0);
            Real waterZ;
            if (terrain->isUnderwater(world.x, world.y, &waterZ, 0, 0)) {
                m_waterAverageZ += z;
                waterSamples++;
            } else {
                m_terrainAverageZ += z;
                terrainSamples++;
            }
        }
    }
    if (terrainSamples == 0)
        terrainSamples = 1;
    if (waterSamples == 0)
        waterSamples = 1;
    m_terrainAverageZ /= terrainSamples;
    m_waterAverageZ /= waterSamples;
}

