// FUNCTION: BFME2 0x002D88A4 size=151 name=?createEvent@Radar@@QAEXPBVCoord3D@@W4RadarEventType@@M@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
void Radar::createEvent(const Coord3D *world, RadarEventType type, Real secondsToLive)
{
	if (!world)
		return;
	RGBAColorInt color1;
	RGBAColorInt color2;
	int i = 0;
	for (; s_radarEventColors[i].type != RADAR_EVENT_NONE; i++) {
		if (s_radarEventColors[i].type == type) {
			color1 = s_radarEventColors[i].color1;
			color2 = s_radarEventColors[i].color2;
			break;
		}
	}
	if (s_radarEventColors[i].type == RADAR_EVENT_NONE) {
		color1 = s_radarDefaultColor1;
		color2 = s_radarDefaultColor2;
	}
	internalCreateEvent(world, type, secondsToLive, &color1, &color2);
}

// FUNCTION: BFME2 0x002D893B size=224 name=?createPlayerEvent@Radar@@QAEXPBURva002D893BColorSource@@PBVCoord3D@@W4RadarEventType@@M@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
void Radar::createPlayerEvent(const Player *player, const Coord3D *world, RadarEventType type, Real secondsToLive)
{
	if (player == NULL || world == NULL)
		return;

	UnsignedByte r, g, b, a;
	RGBAColorInt color[2];

	GameGetColorComponents(player->getPlayerColor(), &r, &g, &b, &a);
	color[0].red = r;
	color[0].green = g;
	color[0].blue = b;
	color[0].alpha = a;

	Real darkScale = -0.75f;
	color[1] = color[0];
	color[1].red += (Int)(color[0].red * darkScale);
	color[1].green += (Int)(color[0].green * darkScale);
	color[1].blue += (Int)(color[0].blue * darkScale);

	internalCreateEvent(world, type, secondsToLive, &color[0], &color[1]);
}

// FUNCTION: BFME2 0x002D8A1B size=220 name=?tryInfiltrationEvent@Radar@@QAEXPBVObject@@@Z evidence=N:ledger tier=A

// FUNCTION: BFME2 0x002D8AF7 size=166 name=?tryEvent@Radar@@QAE_NW4RadarEventType@@PBVCoord3D@@@Z evidence=X:retail PE exports class Coord3D: ??0Matrix4D@@QAE@ABVCoord3D@@@Z tier=A
bool Radar::tryEvent(RadarEventType type, const Coord3D *world)
{
	if (type >= RADAR_EVENT_NONE || !world)
		return false;
	UnsignedInt frame = TheGameClient->getFrame();
	UnsignedInt quietFrames = BfmeClientFramesPerSecond * 10;
	RadarEvent *event = m_events;
	for (int i = 0; i < 64; i++, event++) {
		if (event->m_type == type) {
			Real dx = world->x - event->m_worldLoc.x;
			Real dy = world->y - event->m_worldLoc.y;
			if (dx * dx + dy * dy <= 360000.0f && frame - event->m_createFrame < quietFrames)
				return false;
		}
	}
	createEvent(world, type, 4.0f);
	return true;
}

