void RadarObject::xfer(Xfer *xfer)
{
	if (xfer->IsLightCRC())
		return;
	Xfer::Version version(1, 1);
	*xfer == version;
	ObjectID objectID = m_object ? m_object->getID() : (ObjectID)0;
	XferObjectID(xfer, &objectID);
	if (xfer->IsLoading()) {
		m_object = TheGameLogic->findObjectByID(objectID);
		if (m_object == 0)
			throw XferException(5, 0);
		m_object->m_radarData = this;
	}
	*xfer == m_color;
}

